#include <iostream>
#include <vector>
#include <cmath>
#include <iomanip>

struct Point3D {
    double x, y, z;
};

struct Point2D {
    double x, y;
};

struct Camera3D {
    double ox = 320.0;
    double oy = 20.0;
    double ux = 20.0;
    double uy = 20.0;
    double uz = 20.0;
    double Xx = 0.8 * 3.14159265358979323846;
    double Xy = 0.2 * 3.14159265358979323846;

    Point2D project(const Point3D& p) const {
        double px = ox + p.x * ux * std::cos(Xx) + p.y * uy * std::cos(Xy);
        double py = oy + p.x * ux * std::sin(Xx) + p.y * uy * std::sin(Xy) - p.z * uz;
        return {px, py};
    }
};

double f(double x, double y) {
    return 4.0 * std::sin(x) * std::sin(y);
}

double crossProduct2D(const Point2D& a, const Point2D& b, const Point2D& d) {
    return (b.y - a.y) * (d.x - a.x) - (d.y - a.y) * (b.x - a.x);
}

int main() {
    Camera3D cam;
    double x = 0.0, y = 0.0;
    double xp = 0.2, yp = 0.2;

    Point3D A{x,      y,      f(x, y)};
    Point3D B{x,      y + yp, f(x, y + yp)};
    Point3D C{x + xp, y + yp, f(x + xp, y + yp)};
    Point3D D{x + xp, y,      f(x + xp, y)};

    Point2D pA = cam.project(A);
    Point2D pB = cam.project(B);
    Point2D pC = cam.project(C);
    Point2D pD = cam.project(D);

    double cross = crossProduct2D(pA, pB, pD);

    std::cout << std::fixed << std::setprecision(2);
    std::cout << "Vertex A (2D): (" << pA.x << ", " << pA.y << ")\n";
    std::cout << "Vertex B (2D): (" << pB.x << ", " << pB.y << ")\n";
    std::cout << "Vertex C (2D): (" << pC.x << ", " << pC.y << ")\n";
    std::cout << "Vertex D (2D): (" << pD.x << ", " << pD.y << ")\n";
    std::cout << "Cross product: " << cross << "\n";
    std::cout << "Orientation: " << (cross < 0 ? "FRONT (YELLOW)" : "BACK (GREEN)") << "\n";

    return 0;
}

#include <iostream>
#include <vector>
#include <string>

struct ToneEvent {
    int frequency; // Hz (0 indicates silence / nosound)
    int duration;  // milliseconds
};

class AudioSequencer {
private:
    std::vector<ToneEvent> events;
public:
    void sound(int freq, int duration_ms) {
        events.push_back({freq, duration_ms});
    }

    void nosound(int duration_ms) {
        events.push_back({0, duration_ms});
    }

    // Textbook Example 2: Bouncing ball simulation (bong)
    void simulateBouncingBall(int cao, int thap, int initialCount = 4) {
        int sodem = initialCount;
        while (sodem > 1) {
            sound(thap - 2 * sodem, sodem * 500 / 20);
            nosound(100);
            sound(cao, sodem * 500 / 15);
            nosound(150);
            sodem--;
        }
    }

    void printTimeline() const {
        int currentTime = 0;
        std::cout << "Bouncing Ball Audio Timeline:\n";
        for (const auto& ev : events) {
            if (ev.frequency > 0) {
                std::cout << "[" << currentTime << " - " << currentTime + ev.duration
                          << " ms] PLAY Tone: " << ev.frequency << " Hz\n";
            } else {
                std::cout << "[" << currentTime << " - " << currentTime + ev.duration
                          << " ms] NOSOUND (Silence)\n";
            }
            currentTime += ev.duration;
        }
        std::cout << "Total Effect Duration: " << currentTime << " ms\n";
    }
};

int main() {
    AudioSequencer seq;
    // Simulate ball bounce with cao = 500 Hz, thap = 300 Hz, sodem = 4
    seq.simulateBouncingBall(500, 300, 4);
    seq.printTimeline();
    return 0;
}
